def export_snapshot(state):
    return {
        "snapshot_id": generate_id(),
        "version": 1,
        "source_system": "order-agent",
        "created_at": now_iso(),
        "scope": ["order_status", "customer_id"],
        "payload": {
            "order_status": state["order_status"],
            "customer_id": state["customer_id"],
        },
    }

def import_snapshot(raw):
    if raw.get("version") != 1:
        raise ValueError("unsupported snapshot version")
    if "payload" not in raw:
        raise ValueError("snapshot missing payload")
    return raw["payload"]

function importResearchSnapshot(raw) {
  if (raw.version !== 1) throw new Error("unsupported version");
  const expiry = new Date(raw.expires_at);
  if (Date.now() > expiry.getTime()) throw new Error("snapshot expired");
  return raw.payload;
}
